INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 1, 'sd01-wire', 0, 'lab', 'Первая цепочка', 'Сервис записок: пользователи читают и пишут заметки. Соедините пользователей с сервером приложения, а сервер — с базой данных, чтобы запросы дошли до хранилища. Компоненты уже стоят на поле: нужны связи: потяните от выходного порта (справа) одного компонента ко входному порту (слева) другого.', '', 'Пользователи → сервер приложения → база данных. Сервер не должен обращаться к базе в обход самого себя.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 1, 'sd01-fleet', 1, 'lab', 'Сколько серверов нужно', 'Заметки выросли: 600 чтений и 120 записей в секунду. Один сервер размера S тянет около 300 запросов в секунду, база S — 1000 чтений и 200 записей. Добавьте балансировщик и сервер за ним так, чтобы ни один компонент не был загружен больше чем на 80%, а стоимость не превышала $500 в месяц.', '', 'Нагрузка на сервер: 720 запросов. Три сервера S дают 900 — загрузка ровно 80%. Базе S не хватает: у неё 600/1000 + 120/200 = 120% — нужна M.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 1, 'sd01-bottleneck', 2, 'lab', 'Узкое место', 'Серверов хватает, а сервис всё равно тормозит и теряет запросы. Найдите самый загруженный компонент на схеме (красный) и исправьте именно его — лишних денег не тратьте: бюджет $460.', '', 'Смотрите на полоски загрузки. Приложения простаивают, а база перегружена — сервера тут не причём.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 1, 'sd01-peak', 3, 'lab', 'Пик нагрузки', 'В пик (распродажа, вечер пятницы) нагрузка втрое выше средней: 1800 чтений и 300 записей в секунду. Схема рассчитана на среднюю нагрузку. Доведите её до пика: загрузка компонентов не выше 85%, стоимость не больше $1200 в месяц.', '', 'Прикидывайте по пику, а не по среднему. Приложения: 2100 запросов — например, четыре сервера M. База: M уже не вытянет, нужна L.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 1, 'sd01-latency', 4, 'lab', 'Задержка под нагрузкой', 'Серверы приложения загружены на 90%, и пользователи жалуются на медленные ответы. Загрузка и задержка связаны: чем ближе к 100%, тем длиннее очередь. Добейтесь p99 не больше 150 мс и средней задержки не больше 70 мс.', '', 'Задержка растёт как 1/(1 − загрузка). Уберите перегрев там, где он есть: добавьте серверов, чтобы загрузка упала примерно вдвое.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 1, 'sd01-nines', 5, 'lab', 'Три девятки', 'По договору сервис должен быть доступен не меньше 99,95% времени. Сейчас каждый компонент один, и сбой любого останавливает сервис. Добавьте резервирование: схема должна переживать отказ балансировщика, сервера приложения и лидера базы данных.', '', 'Доступность цепочки — произведение доступностей. Резерв: два балансировщика, три сервера (после потери одного оставшиеся должны вытянуть нагрузку), у базы — реплика и автопереключение.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 1, 'sd01-budget', 6, 'lab', 'Уложиться в бюджет', 'Стартап: бюджет только $330 в месяц, нагрузка скромная — 400 чтений и 60 записей в секунду. Соберите самую дешёвую схему, которая выдерживает нагрузку (загрузка не выше 85%) и не имеет перегруженных компонентов. Размер и число серверов подбирайте сами.', '', 'Два сервера S дают 600 запросов при нагрузке 460 (77%). Балансировщик нужен, если серверов больше одного. База S: 400/1000 + 60/200 = 70% — хватит.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 2, 'sd02-vertical', 0, 'lab', 'Вертикальный рост', 'Сервис вырос до 900 чтений и 100 записей в секунду, а единственный сервер S тянет только 300. Балансировщик и новые серверы пока вводить нельзя: команда небольшая. Масштабируйте вертикально — оставьте один сервер, но возьмите подходящего размера, чтобы загрузка не превышала 80%.', '', 'У сервера L ёмкость 1500 запросов в секунду. Проверьте и базу: при 1000 запросах ей хватит размера M.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 2, 'sd02-horizontal', 1, 'lab', 'Горизонтальный рост', 'Та же нагрузка (1000 запросов в секунду), но теперь масштабируем горизонтально: поставьте балансировщик и несколько одинаковых серверов, чтобы загрузка не превышала 80% и стоимость осталась не больше $520 в месяц. Не забудьте: база тоже должна держать нагрузку.', '', 'Два сервера M дают 1400 запросов — загрузка 71%. Серверы S дороже при такой нагрузке: понадобится пять.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 2, 'sd02-sessions', 2, 'lab', 'Сессии за балансировщиком', 'После того как серверов стало три, пользователи жалуются: вход «слетает» через раз. Сессии хранятся в памяти каждого сервера, а балансировщик отправляет запросы на любой из них. Исправьте схему: вынесите сессии во внешнее хранилище (параметр сервера «Сессии»), чтобы любой экземпляр мог обслужить любого пользователя.', '', 'Выберите сервер приложения на схеме и поменяйте «Сессии» на «во внешнем хранилище».', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 2, 'sd02-l7', 3, 'lab', 'Какой уровень балансировки', 'Команде нужно направлять запросы по пути («/api» — одним сервисам, «/img» — другим) и повторять неудачные запросы. Поменяйте балансировщик так, чтобы он понимал HTTP, но при этом p99 остался не больше 120 мс.', '', 'Уровень L7 разбирает HTTP, но добавляет полторы миллисекунды. Загрузку серверов лучше держать ниже 60%, иначе вырастет очередь.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 2, 'sd02-nplus1', 4, 'lab', 'Запас на один сервер', 'Сервис получает 1000 запросов в секунду. Сейчас два сервера M дают 1400, а когда один из них падает, остаётся 700 — половина запросов теряется. Добавьте запас «N+1»: схема должна переживать отказ любого одного сервера приложения и укладываться в $700 в месяц.', '', 'Нужно, чтобы оставшиеся после потери одного сервера вытягивали 1000. Три сервера M: после потери двух остаётся 1400.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 2, 'sd02-lbha', 5, 'lab', 'Балансировщик тоже ломается', 'Серверы приложения зарезервированы, но балансировщик один. Если он выйдет из строя, сервис полностью недоступен. Сделайте так, чтобы схема переживала отказ балансировщика и не имела единых точек отказа среди балансировщиков и серверов приложения.', '', 'Параметр «Экземпляры» у балансировщика: два экземпляра делят общий адрес.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 2, 'sd02-migrate', 6, 'lab', 'Переезд на горизонталь', 'Итоговое упражнение главы. Сервис — один сервер S с сессиями в памяти и 700 запросами в секунду. Переведите его на горизонтальную схему: балансировщик (с резервом), серверы без состояния, запас на отказ одного сервера и загрузка не выше 80%. Бюджет — $900 в месяц.', '', 'Нужны: пара балансировщиков, сессии во внешнем хранилище, три сервера M (после потери одного остаются два — 1400 запросов), база M.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 3, 'sd03-cdn', 0, 'lab', 'Статика через CDN', 'Сайт раздаёт 20 000 запросов в секунду статики (картинки, скрипты) и 400 динамических чтений при 50 записях. Сейчас статику отдают серверы приложения, и они перегружены. Поставьте перед схемой CDN, чтобы большая часть статики не доходила до серверов: загрузка не выше 80%, CDN отдаёт не меньше 90% статики.', '', 'CDN соединяется с пользователями и дальше передаёт запросы балансировщику. Параметр TTL у CDN — время жизни копий: 300 секунд даёт 90% попаданий.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 3, 'sd03-cdn-ttl', 1, 'lab', 'Время жизни в CDN', 'CDN уже стоит, но с TTL в 30 секунд: копии быстро устаревают, доля попаданий низкая, а серверы приложения перегружены промахами. Подберите TTL так, чтобы CDN отдавал не меньше 90% статики. Заодно подумайте: что вы делаете с устареванием? (В реальности — версия в имени файла.)', '', 'Допустимые значения TTL: 30, 300 и 3600 секунд. Чем больше значение, тем выше доля попаданий.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 3, 'sd03-cache', 2, 'lab', 'Кэш для чтений', 'Чтений стало 1800 в секунду при 60 записях, а база S тянет лишь 1000 чтений. Рабочий набор — 10 ГБ (из 100 ГБ данных). Добавьте кэш (cache-aside) между приложением и базой: доля попаданий не меньше 85%, загрузка не выше 80%, а стоимость не больше $740 в месяц — дешевле, чем просто взять базу M.', '', 'Попадание зависит от размера кэша относительно рабочего набора (10 ГБ) и TTL. Кэш на 9 ГБ с TTL 3600 даёт около 88%.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 3, 'sd03-size', 3, 'lab', 'Размер кэша', 'Кэш работает, но его доля попаданий всего около 55%, и база на пределе. Рабочий набор — 8 ГБ. Подберите размер и время жизни кэша так, чтобы кэш отдавал не меньше 85% чтений, но не тратьте лишнего: бюджет на кэш ограничен общей суммой $700.', '', 'Сейчас кэш 2 ГБ с TTL 30. Увеличьте память до размера рабочего набора и поставьте TTL подольше.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 3, 'sd03-writeback', 4, 'lab', 'Много записей: write-back', 'Сервис счётчиков получает 800 чтений и 700 записей в секунду. База M выдерживает только 600 записей, поэтому она перегружена. Потеря нескольких секунд счётчиков допустима. Смените политику записи кэша, чтобы база выдерживала нагрузку, не увеличивая её размер.', '', 'Политика write-back накапливает записи в кэше и сбрасывает в базу пачками — так в базу попадает лишь часть записей. Параметр политики показывается в настройках кэша.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 3, 'sd03-cache-ha', 5, 'lab', 'Что, если кэш пропадёт', 'Схема держится на кэше: он принимает 90% чтений, а база рассчитана только на оставшиеся 10%. При отказе кэша база падает. Сделайте схему устойчивой: она должна переживать отказ кэша (проверка «Отказ» → «кэша»), не имея единых точек отказа среди кэша и серверов приложения.', '', 'У кэша есть параметр «Реплики». С репликой после отказа основного узла кэш продолжает работать.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 3, 'sd03-final', 6, 'lab', 'Сайт со статикой и кэшем', 'Итоговое упражнение главы. Магазин: 10 000 запросов статики, 2500 чтений и 100 записей в секунду, 200 ГБ данных, рабочий набор 10 ГБ. Соберите схему: CDN (≥90% статики), кэш (≥85% чтений), загрузка не выше 80%, схема переживает отказ кэша и сервера, бюджет — $1100 в месяц.', '', 'CDN с TTL 300, кэш около 10 ГБ с TTL 3600 и репликой, пять серверов M (на отказ одного останется 2800), база S хватит (кэш снимает чтения), балансировщик.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 4, 'sd04-replicas', 0, 'lab', 'Реплики под чтения', 'Чтений 2500 в секунду при 100 записях. База S тянет 1000 чтений, и она перегружена. Кэша нет. Добавьте реплики (параметр базы «Реплики на шард»): загрузка не выше 80%, стоимость не больше $1200 в месяц. Подумайте: что дешевле — реплики или база покрупнее?', '', 'Каждая реплика S добавляет 1000 чтений. Нужно 4 реплики: 2500 / 4000 = 63%. База M с одной репликой даёт 83% — не хватает.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 4, 'sd04-failover', 1, 'lab', 'Автопереключение лидера', 'Сейчас у базы есть реплика, но при отказе лидера ничего не происходит: запись останавливается, пока администратор не проснётся. Включите автопереключение, чтобы схема переживала отказ лидера базы данных.', '', 'У базы есть параметр «Автопереключение» и «Реплики на шард». Нужна хотя бы одна реплика и включённое автопереключение.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 4, 'sd04-lag', 2, 'lab', 'Отставание реплик', 'Пользователи видят старые данные: реплики отстают. Запись нагружает базу S сильнее всего: отставание реплик больше 100 мс. Уменьшите отставание до 50 мс, не переходя на синхронную репликацию — увеличьте базу, чтобы на ней записи занимали меньше времени.', '', 'Отставание асинхронных реплик растёт с загрузкой записи: на базе M при тех же записях оно заметно меньше.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 4, 'sd04-sync', 3, 'lab', 'Синхронная репликация', 'Платёжный сервис не может потерять подтверждённую запись: после отказа лидера реплика обязана иметь все данные. Включите синхронную репликацию, чтобы отставание было нулевым, но уложитесь в p99 не больше 140 мс.', '', 'Параметр «Репликация» у базы: «синхронная». Она добавляет несколько миллисекунд к записи. Серверы не должны быть перегружены, иначе p99 вырастет.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 4, 'sd04-nines', 4, 'lab', 'Четыре девятки', 'Договор требует доступности не ниже 99,99%. Балансировщик и серверы уже зарезервированы, но база одна — именно она тянет доступность вниз. Добавьте реплику и автопереключение так, чтобы доступность схемы достигла 99,99%.', '', 'Доступность одной базы — 99,9%. Две копии с автопереключением дают около 99,9999%.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 4, 'sd04-lead-size', 5, 'lab', 'Реплика слабее лидера', 'Ограничение «реплика не слабее лидера» нельзя показать прямой настройкой, но можно проверить по загрузке: в этой схеме база L с репликами, и после отказа лидера оставшиеся реплики должны держать нагрузку. Подберите число реплик так, чтобы схема пережила отказ базы с запасом: загрузка при отказе не больше 100%, в обычном режиме — до 70%.', '', 'При отказе одной реплики оставшиеся делят чтения. Две реплики L: чтения 12 000 / 16 000 = 75% — много; три реплики: после потери одной остаётся две — 75% при отказе и 50% в норме.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 5, 'sd05-write-shards', 0, 'lab', 'Упёрлись в запись', 'Сервис принимает 1500 записей в секунду, а база S тянет 200, M — 600, L — 1500 (в обрез). Реплики запись не ускорят. Разрежьте данные на шарды (параметр «Шарды» у базы): загрузка не выше 80%, стоимость не больше $1600 в месяц.', '', 'Записи делятся между шардами поровну (при хеше). Четыре шарда M: по 375 записей на шард — 63%. Столько же стоят десять шардов S, но M проще.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 5, 'sd05-monotonic', 1, 'lab', 'Ключ растёт со временем', 'Данные уже разрезаны на четыре шарда по диапазонам ключа, но ключ — время создания записи: все новые записи попадают в последний шард. Перекос мешает: смените способ разбиения так, чтобы на самый нагруженный шард приходилось не больше 40% нагрузки, а общая загрузка не превышала 80%.', '', 'У базы есть параметр «Ключ шардирования»: хеш или диапазон. Хеш распределяет записи поровну.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 5, 'sd05-hotkey', 2, 'lab', 'Горячий ключ', 'У сервиса есть «знаменитость»: 20% запросов приходится на один ключ. Тогда на одном шарде оказывается 20% плюс его доля от остального. Сейчас четыре шарда M, и самый нагруженный перегружен. Что дешевле: больше шардов или шарды покрупнее? Добейтесь загрузки не выше 80% при стоимости не больше $1800.', '', 'Доля горячего шарда = горячий ключ + остальное / число шардов. Увеличивать число шардов выгодно слабо: 20% не уйдут. Крупные шарды помогают сильнее.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 5, 'sd05-with-replicas', 3, 'lab', 'Шарды и реплики вместе', 'Данные: 3000 чтений и 900 записей в секунду. Нужно и разрезать (запись), и реплицировать (чтения и отказоустойчивость). Соберите базу из шардов M с репликами и автопереключением: загрузка не выше 80%, схема переживает отказ базы, бюджет — $2700 в месяц.', '', 'Три шарда M: по 300 записей (50%); чтений по 1000 на шард, реплика M тянет 3000. Включите автопереключение.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 5, 'sd05-nosql', 4, 'lab', 'Выбор хранилища', 'Сервис хранит события по ключу, без соединений и сложных запросов: подходит NoSQL, которое примерно в 1,8 раза быстрее на простых операциях. При 1500 записях в секунду уложите всю схему в $1100: выберите тип «NoSQL» и подберите шарды.', '', 'NoSQL M тянет около 1080 записей в секунду на шард. Два шарда: 750 на шард — 69%.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 5, 'sd05-final', 5, 'lab', 'Социальная сеть: перекос и надёжность', 'Итоговое упражнение главы. Лента событий: 3000 чтений и 1200 записей в секунду, ключи растут со временем, 10% запросов приходится на самый популярный ключ. Соберите базу: хеш-шардирование, реплики и автопереключение, загрузка не выше 85%, переживание отказа базы, бюджет — $3500 в месяц.', '', 'Хеш убирает перекос по времени, но горячие 10% остаются: крупные шарды помогают. Подойдут три шарда M с репликой или два шарда L.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 6, 'sd06-retry-storm', 0, 'lab', 'Шторм повторов', 'База S перегружена: чтений 1300 при пределе 1000. Приложение при ошибке повторяет запрос к базе до трёх раз без паузы, и нагрузка на базу растёт ещё сильнее — сервис не может подняться. Остановите шторм: включите автомат разрыва (circuit breaker) — когда база перегружена, он обрывает повторы, — чтобы доля успешных ответов была не ниже 72%.', '', 'У сервера приложения есть параметры «Повторы к БД» и «Автомат разрыва» (они показаны в этом упражнении). Включите автомат или обнулите повторы.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 6, 'sd06-idempotency', 1, 'lab', 'Двойное списание', 'Платёжный сервис: клиенты повторяют запрос, если не получили ответ вовремя. Из-за этого иногда деньги списываются дважды. Включите ключи идемпотентности (параметр сервера), оставьте хотя бы один повтор — клиенты и сервер повторяют запросы — и включите автомат разрыва, чтобы повторы не усиливали перегрузку.', '', 'Параметры сервера приложения: «Ключи идемпотентности» — включить; «Повторы к БД» — не меньше 1; «Автомат разрыва» — включить.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 6, 'sd06-strong', 2, 'lab', 'Строгая согласованность', 'Сервис балансов не вправе терять подтверждённую запись и показывать старый баланс. Соберите базу из трёх копий (лидер и две реплики) с синхронной репликацией и автопереключением: отставание реплик — ноль, схема переживает отказ базы, p99 не больше 160 мс.', '', 'База: «Реплики на шард» — 2, «Репликация» — синхронная, «Автопереключение» — включить. Синхронность добавляет несколько миллисекунд к записи.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 6, 'sd06-eventual', 3, 'lab', 'Согласованность в конечном счёте', 'Лента новостей допускает небольшое отставание: свежесть в несколько сотен миллисекунд никому не мешает, зато нужны быстрые чтения и дешёвая запись. Оставьте асинхронную репликацию с двумя репликами и убедитесь, что отставание не больше 200 мс, схема переживает отказ базы, а p99 не больше 100 мс.', '', 'Синхронные реплики здесь не нужны: они замедляют запись. Выберите «асинхронная».', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 6, 'sd06-redelivery', 4, 'lab', 'Повторная доставка из очереди', 'Заказы принимаются через очередь, и обработчики разбирают её с доставкой «не менее одного раза»: одно сообщение иногда приходит дважды. Соберите схему «сервер → очередь → обработчики → база» с идемпотентными обработчиками, чтобы очередь разбиралась без отставания (после пика в 60 с), а обработчики были загружены не выше 90%.', '', 'Параметр «Идемпотентная обработка» у обработчика. Нагрузка записи 400 в секунду: три обработчика S тянут 450.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 6, 'sd06-final', 5, 'lab', 'Платёжный контур', 'Итоговое упражнение главы. Платёжный сервис: надёжность важнее скорости. Нужны: ключи идемпотентности, автомат разрыва, база с синхронной репликой и автопереключением, пара балансировщиков, схема переживает отказ базы и сервера приложения, загрузка не выше 80%, бюджет $1500 в месяц.', '', 'Три сервера M (после потери одного 1400 запросов — хватает), база M с репликой, синхронная, с автопереключением, пара балансировщиков.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 7, 'sd07-search', 0, 'lab', 'Поиск вынесен из базы', 'Половина из 800 чтений в секунду — поисковые запросы по тексту, и база их обрабатывает в несколько раз тяжелее обычных: она перегружена. Добавьте поисковый индекс и соедините с ним сервер приложения, чтобы база разгрузилась: загрузка не выше 80%.', '', 'Палитра содержит «Поиск». Свяжите сервер приложения с поиском: поисковые запросы пойдут туда, а база останется для обычных чтений.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 7, 'sd07-search-shards', 1, 'lab', 'Шарды и реплики поиска', 'Индекс вырос до 150 ГБ, а шард должен быть не больше 40 ГБ. Поисковых запросов — 1000 в секунду, одна реплика тянет 1200. Подберите шарды (по объёму) и реплики (по нагрузке): загрузка не выше 80%, схема переживает потерю реплики поиска, стоимость не больше $1500 в месяц.', '', 'Шарды: 150 / 40 → четыре (по ~37 ГБ). Реплики: одной не хватает (83%), нужны две; кроме того, вторая реплика переживёт отказ первой. Цена: 150 × шарды × реплики.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 7, 'sd07-blob', 2, 'lab', 'Файлы — в объектное хранилище', 'Сайт отдаёт 8000 запросов в секунду картинок и видео прямо через серверы приложения: они тратят силы на передачу байтов. Подключите объектное хранилище и соедините с ним сервер приложения — статика пойдёт мимо него, — и заодно уменьшите парк: стоимость не больше $300 в месяц при загрузке не выше 80%.', '', 'Хранилище обслуживает статику, сервер остаётся для динамики. Тогда хватит одного сервера M и базы S. Балансировщик можно не ставить, если сервер один.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 7, 'sd07-cdn-blob', 3, 'lab', 'CDN перед хранилищем', 'Файлы лежат в объектном хранилище, но пользователи по всему миру получают их медленно, а 30 000 запросов в секунду стоят дорого. Поставьте CDN перед хранилищем (CDN соединяется с хранилищем): не меньше 90% статики отдаётся из CDN, схема укладывается в $700 в месяц.', '', 'CDN принимает пользователей, статику забирает у хранилища при промахе, а динамические запросы передаёт балансировщику. TTL 300 даёт 90%.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 7, 'sd07-search-ha', 4, 'lab', 'Отказ реплики поиска', 'Поиск стоит одним узлом: при его отказе пользователи получают ошибки на каждый поисковый запрос. Добавьте реплику поиска так, чтобы схема переживала отказ реплики и нагрузка в этот момент оставалась в норме.', '', 'У поиска параметр «Реплики»: нужно хотя бы две. Каждая реплика тянет 1200 запросов, нагрузка 600 — после потери одной загрузка 50%.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 7, 'sd07-final', 5, 'lab', 'Каталог с картинками и поиском', 'Итоговое упражнение главы. Маркетплейс: 20 000 запросов статики, 1200 чтений (половина — поиск по каталогу в 90 ГБ) и 100 записей в секунду. Соберите схему: CDN перед хранилищем (≥90%), поисковый индекс с шардами по объёму и двумя репликами, база без перегрузки, загрузка не выше 80%, переживание отказа поиска, бюджет $2000 в месяц.', '', 'Шарды поиска: 90 / 40 → три. Реплики: две. CDN → хранилище, приложение → поиск и хранилище. Три сервера M и база M.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 8, 'sd08-spike', 0, 'lab', 'Сглаживание пика записи', 'В пик сервис получает 2000 записей в секунду, а база M выдерживает 600: без буфера она перегружена. Поставьте между сервером приложения и базой очередь с обработчиками. Обработчики должны разбирать очередь не быстрее, чем база способна писать: загрузка базы не выше 80%, а после пика в 5 секунд очередь разбирается не дольше чем за 30 секунд.', '', 'База принимает столько записей, сколько успевают провести обработчики: два обработчика S — 300 записей в секунду: база загружена на 67% (с учётом чтений). Отставание: (2000 − 300) / 300 × 5 ≈ 28 с.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 8, 'sd08-workers', 1, 'lab', 'Сколько обработчиков', 'Очередь уже есть, но обработчиков слишком мало: после пика в 20 секунд очередь разбирается слишком долго. Поступает 1500 записей в секунду, база L принимает до 1500. Подберите обработчиков так, чтобы очередь разбиралась не дольше 20 секунд, а база при этом была загружена не больше чем на 80%.', '', 'Отставание = (приток − разбор) / разбор × длина пика. Для 20 секунд нужен разбор не меньше 750 в секунду, но и не больше 1200 (80% базы). Два обработчика M — 800.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 8, 'sd08-partitions', 2, 'lab', 'Партиции очереди', 'Поток — 30 000 сообщений в секунду, а одна партиция пропускает 20 000. Подберите число партиций, чтобы очередь была загружена не выше 80% и переживала отказ узла брокера (для этого нужно не меньше трёх партиций).', '', 'Две партиции дают 40 000 — 75%, но для переживания отказа нужны три: 30 000 / 60 000 = 50%.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 8, 'sd08-dlq', 3, 'lab', 'Очередь недоставленных', 'Из-за одного «ядовитого» сообщения обработчик зацикливается и блокирует очередь. Включите очередь недоставленных (DLQ) и сделайте обработку идемпотентной, чтобы повторы были безопасны, а очередь разбиралась без отставания.', '', 'У очереди — параметр «Очередь недоставленных», у обработчика — «Идемпотентная обработка» (оба показаны в этом упражнении).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 8, 'sd08-spot', 4, 'lab', 'Дешёвые обработчики', 'Ночная обработка заказов не срочна, и её можно запускать на прерываемых серверах (спот): они втрое дешевле, но могут исчезнуть. Переведите обработчиков на спот, оставьте не меньше двух (чтобы потеря одного не останавливала очередь) и уложитесь в $850 всей схемой — очередь при этом должна разбираться без отставания.', '', 'Параметр «Тариф» обработчика (виден в упражнении): спот стоит 30% от обычной цены. Нужно не меньше двух экземпляров — иначе точка отказа.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 8, 'sd08-final', 5, 'lab', 'Конвейер обработки', 'Итоговое упражнение главы. Сервис заказов: 600 чтений и 900 записей в секунду, после пика в 15 секунд очередь должна разбираться не дольше 30 секунд. Соберите схему: очередь с очередью недоставленных, идемпотентные обработчики (не меньше двух), база не выше 80%, схема переживает отказ обработчика, бюджет — $1700 в месяц.', '', 'База L принимает 1500 записей. Два обработчика M — 800 в секунду: 53% базы, отставание (900 − 800)/800 × 15 ≈ 2 с. Включите DLQ и идемпотентность.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 9, 'sd09-limiter-attack', 0, 'lab', 'Ограничитель от атаки', 'Обычно сервис получает около 1500 запросов в секунду, но сейчас идёт атака: 6000. Серверы приложения (три M — 2100 запросов) перегружены. Поставьте ограничитель на входе и подберите предел: серверы загружены не больше чем на 95%, а до сервиса доходит не меньше 28% запросов (иначе вместе с атакой вы режете своих).', '', 'Ограничитель ставится между балансировщиком и серверами: lb → ограничитель → сервер. Предел от 1700 до 1995: 6000 × 0,28 ≈ 1680, 2100 × 0,95 ≈ 1995.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 9, 'sd09-limit-normal', 1, 'lab', 'Не режьте своих', 'Ограничитель уже стоит, но предел задан слишком строго (800 запросов в секунду), а обычная нагрузка — 1500. Часть настоящих пользователей получает отказ. Поднимите предел так, чтобы не меньше 99% запросов проходили, но защита сохранялась: предел не больше 2500.', '', 'Предел должен быть чуть выше обычной нагрузки (1500), но ниже ёмкости серверов (2100).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 9, 'sd09-fail-fast', 2, 'lab', 'Отказ базы и повторы', 'Приложение повторяет запросы к базе до трёх раз без паузы. Когда база выходит из строя, повторы лавиной ложатся на единственную копию и не дают ей подняться. Сделайте так, чтобы схема переживала отказ базы: реплика с автопереключением и автомат разрыва в приложении.', '', 'У базы — «Реплики на шард» ≥ 1 и «Автопереключение»; у приложения — «Автомат разрыва» (виден в упражнении).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 9, 'sd09-degrade', 3, 'lab', 'Кэш на случай сбоя', 'Страницы товаров читаются 2000 раз в секунду, и при перегрузке или отказе базы пользователи видят ошибки. Поставьте кэш, который принимает почти все чтения (не меньше 85%) и сохранит работу сайта, когда база тормозит: схема должна переживать отказ кэша (у кэша есть реплика) и не иметь единой точки отказа среди серверов приложения.', '', 'Кэш около 6 ГБ с TTL 3600 и репликой; рабочий набор — 6 ГБ. Серверы приложения: три и больше.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 9, 'sd09-final', 4, 'lab', 'Защитный контур', 'Итоговое упражнение главы. Соберите устойчивую схему: ограничитель на входе (предел 1500–2500 при обычных 1500), приложение с автоматом разрыва, база с репликой и автопереключением, кэш с репликой. Схема переживает отказ базы, кэша и сервера приложения, серверы загружены не выше 80%, бюджет $1500 в месяц.', '', 'lb → ограничитель → серверы; четыре сервера M (запас на отказ одного); кэш около 4 ГБ с репликой; база M с репликой и автопереключением.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 10, 'sd10-gateway', 0, 'lab', 'Шлюз на входе', 'Монолит стоит за балансировщиком, а команда хочет единую входную точку: авторизацию, лимиты и маршрутизацию. Добавьте API-шлюз между пользователями и балансировщиком, зарезервируйте его (не меньше двух экземпляров), чтобы шлюз не стал единой точкой отказа: схема переживает отказ шлюза.', '', 'Пользователи → шлюз → балансировщик → серверы. Параметр «Экземпляры» шлюза — 2.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 10, 'sd10-split', 1, 'lab', 'Разрезаем монолит', 'Монолит получает 2500 чтений и 300 записей в секунду, и единственная база перегружена. Разрежьте его на два сервиса: «Заказы» (70% трафика) и «Каталог» (30%) — каждый со своей базой. Шлюз делит трафик по весам сервисов (параметр «Доля трафика»: 7 и 3). Загрузка всех компонентов — не выше 80%.', '', '«Заказы» — вес 7, база L (на ней 1750 чтений и 210 записей). «Каталог» — вес 3, база M (750 чтений, 90 записей). Серверы: у заказов четыре M (1960 запросов при ёмкости 2800), у каталога два M.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 10, 'sd10-weights', 2, 'lab', 'Доли трафика между сервисами', 'Два сервиса за шлюзом: «Основной» (четыре сервера M) и «Дополнительный» (один сервер M). Трафик делится поровну, и маленький сервис перегружен. Настройте доли трафика (параметр «Доля трафика») пропорционально ёмкости: загрузка всех компонентов — не выше 90%.', '', 'Ёмкость 2800 против 700 — это 4 : 1. Поставьте вес 4 у основного и 1 у дополнительного.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 10, 'sd10-own-db', 3, 'lab', 'База на сервис', 'Два сервиса — «Заказы» и «Платежи» — ходят в одну общую базу, и выкладка одного регулярно ломает другой. Разделите хранилище: у каждого сервиса должна быть своя база. Базы средние, общая загрузка не выше 80%, бюджет $1900 в месяц.', '', 'Нужны две базы, каждая подключена только к своему сервису. Поставьте вторую базу и перенесите связь платежей на неё.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 10, 'sd10-final', 4, 'lab', 'Магазин из трёх сервисов', 'Итоговое упражнение главы. Соберите магазин из трёх сервисов — «Каталог» (вес 5), «Заказы» (вес 3) и «Платежи» (вес 2), у каждого своя база. Нагрузка: 3000 чтений и 500 записей в секунду. Шлюз в двух экземплярах, загрузка не выше 80%, схема переживает отказ шлюза и сервера приложения, бюджет — $3000 в месяц.', '', 'Доли 5:3:2 — это 1750, 1050 и 700 запросов. Каталог: четыре сервера M и база L; заказы: три сервера M и база M; платежи: два сервера M и база M. У каждого сервиса запас на потерю одного экземпляра.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 11, 'sd11-ws-gateway', 0, 'lab', 'Шлюзы WebSocket', 'Чат получает 90 000 одновременных соединений, а обычные запросы (история) идут через балансировщик. Один шлюз WebSocket держит 15 000 соединений. Добавьте шлюзы между пользователями и серверами приложения, свяжите их и подберите число экземпляров так, чтобы шлюзы были загружены не больше чем на 80%.', '', 'Пользователи → шлюз WebSocket → сервер приложения. Для 90 000 соединений понадобится восемь экземпляров (67–75%).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 11, 'sd11-ws-scale', 1, 'lab', 'Триста тысяч соединений', 'Аудитория выросла: 300 000 одновременных соединений. Подберите число шлюзов WebSocket: загрузка не выше 80% и запас на потерю одного шлюза без перегрузки остальных. Бюджет — $3500 в месяц.', '', '300 000 / (15 000 × 0,8) = 25 шлюзов; при потере одного загрузка вырастет с 80% до 83% — поэтому лучше 26.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 11, 'sd11-messages', 2, 'lab', 'Поток сообщений', '90 000 соединений по 0,03 сообщения в секунду — 2700 сообщений в секунду. Сейчас они пишутся прямо в базу, и она перегружена. Пропустите сообщения через очередь и обработчиков: свяжите сервер с очередью, очередь — с обработчиками, обработчиков — с базой. База и серверы — не выше 80%, очередь разбирается без отставания (пик — 10 секунд, допустимо 5 с).', '', 'Нужен разбор не меньше 2700 в секунду: семь обработчиков M — 2800. Приложению нужно около шести серверов M.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 11, 'sd11-presence', 3, 'lab', 'Присутствие в кэше', 'Список друзей показывает «онлайн» — это 3000 запросов статуса в секунду к небольшому рабочему набору (около 2 ГБ). База S не справляется. Поставьте кэш статусов с долгим временем жизни записей: кэш отдаёт не меньше 90% чтений, база загружена не выше 80%.', '', 'Кэш 2–3 ГБ с TTL 3600 — около 94% попаданий; TTL 300 даст чуть меньше 90%.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 11, 'sd11-final', 4, 'lab', 'Чат целиком', 'Итоговое упражнение главы. Мессенджер: 150 000 соединений, 0,02 сообщения в секунду на соединение (3000 сообщений в секунду), статусы и история — 2000 чтений, 100 записей. Соберите схему: шлюзы WebSocket (не выше 80%, с запасом на потерю одного), очередь с обработчиками (без отставания: пик 10 с, допустимо 5 с), кэш статусов (≥90%), база не выше 80%, бюджет — $5000 в месяц.', '', 'Шлюзы: 150 000 / 12 000 = 13–14. Обработчики: 3000 сообщений — восемь M. Кэш 3 ГБ с TTL 3600. Серверы приложения принимают и обычные запросы, и 3000 сообщений в секунду: около десяти M.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 12, 'sd12-pull-fix', 0, 'lab', 'Лента при чтении перегружает базу', 'Лента собирается при открытии (pull): у каждого автора в среднем 50 подписчиков, и при 2000 чтений в секунду база L перегружена лишними запросами. Полная рассылка при записи (push) тоже не подходит: 50 записей в секунду превращаются в 2500. Выберите режим ленты у сервера приложения так, чтобы база была загружена не выше 80%. Параметр «Лента» виден в упражнении.', '', 'Pull умножает чтения в 3,5 раза, push умножает записи в 50. Гибрид умножает и то и другое всего в 1,5 раза.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 12, 'sd12-feed-cache', 1, 'lab', 'Кэш для готовых лент', 'Читателей стало больше: 4000 открытий ленты в секунду, рабочий набор — 8 ГБ из 200. База M не вытягивает чтения. Оставьте гибридный режим ленты и поставьте кэш: кэш отдаёт не меньше 90%, база загружена не выше 80%, серверы — тоже. Бюджет — $1600 в месяц.', '', 'Кэш около 8 ГБ с TTL 3600 — около 94% попаданий, база увидит лишь 6% чтений. Серверов приложения хватит восьми M.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 12, 'sd12-push-queue', 2, 'lab', 'Рассылка постов через очередь', 'У сервиса небольшие аудитории (10 подписчиков у автора), поэтому выбран push: каждый пост рассылается в ленты. При 400 постах в секунду это 4000 записей в ленты — всё сразу база не выдержит. Пропустите запись через очередь с обработчиками: база L загружена не выше 80%, очередь разбирается после 10-секундного пика не дольше 45 секунд. Режим ленты — push.', '', 'Обработчики определяют темп записи в базу: два обработчика M — 800 в секунду (53% базы L). Отставание: (4000 − 800) / 800 × 10 = 40 с.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 12, 'sd12-celebrity', 3, 'lab', 'Знаменитости', 'В сервисе есть авторы-знаменитости: средняя аудитория автора — 300 подписчиков. Полный push даст умножение записей в 300 раз, чистый pull — в 16 раз чтений. Выберите гибрид и поставьте кэш, чтобы база M была загружена не выше 80% при 3000 чтений и 40 записях в секунду.', '', 'Гибрид: чтения ×4, записи ×4. Кэш с хорошим попаданием сводит дополнительные чтения почти к нулю: 6 ГБ с TTL 3600.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 12, 'sd12-final', 4, 'lab', 'Социальная сеть', 'Итоговое упражнение главы. Лента: 8000 открытий и 100 постов в секунду, 100 подписчиков у автора в среднем, 300 ГБ данных (рабочий набор 12 ГБ). Соберите схему: гибридная лента, кэш (≥90%), база с репликой и автопереключением (переживает отказ базы и кэша), серверы приложения с запасом на потерю одного, всё — не выше 80%, бюджет $3500 в месяц.', '', 'Кэш 12 ГБ с репликой и TTL 3600; серверов приложения — пятнадцать M (нагрузка 8100 запросов, запас на отказ одного); база M с репликой и автопереключением.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 13, 'sd13-shortener', 0, 'lab', 'Сокращатель ссылок', 'Сокращатель: 4000 переходов и 40 созданий ссылок в секунду, 500 ГБ данных, рабочий набор около 5 ГБ. База S не тянет такие чтения. Поставьте кэш (≥90% попаданий) с репликой, чтобы схема переживала отказ кэша, и уложитесь в $1400 в месяц. Загрузка — не выше 80%.', '', 'Кэш 5 ГБ с TTL 3600 даёт около 93%; с репликой переживёт отказ. Серверов приложения — восемь M, база S хватит (чтения почти все из кэша).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 13, 'sd13-counter', 1, 'lab', 'Счётчик просмотров', 'Счётчики просмотров — 3000 обновлений в секунду плюс 500 чтений. Каждое обновление пишет в базу, и она перегружена: база M тянет 600 записей. Допустима потеря нескольких секунд счётчиков. Включите отложенную запись кэша (write-back) и подберите базу: загрузка не выше 80%, бюджет $1800 в месяц. Поможет и тип «NoSQL».', '', 'Write-back оставляет в базе 40% записей: 1200 в секунду. NoSQL M тянет 1080 записей: два шарда — 56%. Приложению нужно семь серверов M.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 13, 'sd13-ratelimiter', 2, 'lab', 'Общий ограничитель', 'Ограничитель частоты на нескольких серверах должен иметь общий счётчик в быстром хранилище. Соберите схему: ограничитель на входе (предел не меньше 3000 — иначе обрежем обычный трафик в 2700 запросов), кэш для общих счётчиков с репликой (переживает отказ), серверы приложения не выше 80%.', '', 'lb → ограничитель → серверы; кэш связан с серверами, у кэша — реплика. Предел 3000–3500.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 13, 'sd13-pastebin', 3, 'lab', 'Хранение блоков', 'Сервис хранения фрагментов: 4000 запросов в секунду на раздачу готовых файлов, 800 чтений и 50 записей метаданных. Файлы сейчас отдают серверы приложения. Вынесите их: CDN перед объектным хранилищем (≥90%), серверы и база — на метаданных. Загрузка не выше 80%, бюджет $650 в месяц.', '', 'CDN → хранилище (статика мимо серверов), динамика через балансировщик. Серверов M хватит двух, база M (чтения метаданных 800 в секунду не помещаются в S).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 13, 'sd13-final', 4, 'lab', 'Сокращатель со статистикой', 'Итоговое упражнение главы. Сокращатель со счётчиком кликов: 3000 переходов и 3000 учтённых кликов-записей в секунду. Соберите схему: кэш с write-back и репликой (попадания ≥70%: при половине записей кэш отдаёт меньше), NoSQL-база с шардами и репликой с автопереключением, загрузка не выше 80%, схема переживает отказ базы, кэша и сервера приложения, бюджет $3200 в месяц.', '', 'Серверов M — двенадцать (6000 запросов); кэш 4 ГБ с репликой и write-back; NoSQL M: два шарда с репликой и автопереключением.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 14, 'sd14-monitor', 0, 'lab', 'Мониторинг и три девятки', 'Сервис работает без мониторинга, и о сбоях узнают от пользователей. Добавьте мониторинг (метрики, журналы, оповещения) и дотяните схему до цели по доступности 99,9% при p99 не больше 120 мс. Сейчас база одна и тянет доступность вниз.', '', 'Компонент «Мониторинг» — на схему (связи не нужны). Для 99,9% база должна иметь реплику и автопереключение.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 14, 'sd14-slo-three', 1, 'lab', 'SLO 99,95%: дёшево', 'Цель по доступности — 99,95%. Соберите минимальную по стоимости схему, которая её выполняет: мониторинг обязателен, схема переживает отказ базы и сервера приложения, бюджет — $700 в месяц.', '', 'Один балансировщик даёт потолок 99,95% — нужно два. База S с репликой и автопереключением, два-три сервера M.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 14, 'sd14-slo-five', 2, 'lab', 'Пять девяток', 'Для платёжного шлюза цель — доступность не ниже 99,999%. Каждый компонент должен быть зарезервирован: балансировщики, серверы приложения и база. Соберите схему с мониторингом и бюджетом $1500 в месяц, которая достигает цели и переживает отказ любого компонента.', '', 'Два балансировщика, три сервера, база с двумя репликами и автопереключением даёт около 99,9999%.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 14, 'sd14-headroom', 3, 'lab', 'Запас по ёмкости', 'Команда мониторинга настроила оповещение на загрузку 60%: выше — повод для тревоги. Нагрузка: 1500 чтений и 200 записей в секунду. Доведите схему до состояния, когда ни один компонент не загружен больше чем на 60%, с мониторингом и бюджетом $1300 в месяц.', '', 'Серверы: 1700 запросов — два L (3000, 57%). База M при чтениях 1500 — 83%: нужна реплика или размер L.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 14, 'sd14-latency', 4, 'lab', 'Бюджет задержки', 'SLO по задержке: p50 не больше 40 мс и p99 не больше 80 мс. Читают 2700 раз в секунду, база M почти на пределе, а серверы приложения при высокой загрузке копят очередь. Добавьте кэш (≥80%) и уменьшите загрузку серверов, чтобы выполнить цели.', '', 'Задержка растёт как 1/(1 − загрузка): серверы держите около 50%. Кэш 5 ГБ с TTL 3600 снимет чтения с базы.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 14, 'sd14-final', 5, 'lab', 'Схема с целями по надёжности', 'Итоговое упражнение главы. Сервис с SLO: доступность ≥ 99,995%, p99 ≤ 100 мс, загрузка не выше 60%. Читают 3000 раз и пишут 150 раз в секунду. Соберите схему с мониторингом: два балансировщика, кэш с репликой, база с репликой и автопереключением, переживание отказа базы, кэша и сервера приложения, бюджет $2200 в месяц.', '', 'Серверов M — около девяти (загрузка ~50%), кэш 6 ГБ с репликой и TTL 3600, база M с репликой и автопереключением, мониторинг.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 15, 'sd15-zone-app', 0, 'lab', 'Серверы по зонам', 'База уже размещена в трёх зонах, а серверы приложения стоят в одной: при отказе зоны они пропадают все. Разнесите серверы по трём зонам (параметр «Размещение») и добавьте их столько, чтобы после потери зоны (минус треть серверов) остальные вытягивали 1700 запросов в секунду. Схема должна переживать отказ зоны.', '', 'Пять серверов M: после потери зоны остаётся три — 2100 запросов. Четырёх мало: останется два (1400).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 15, 'sd15-zone-db', 1, 'lab', 'База по зонам', 'Серверы приложения разнесены по зонам, но база стоит в одной зоне вместе со своей репликой: потеря зоны останавливает запись. Разместите базу в трёх зонах с репликой и автопереключением, чтобы схема переживала отказ зоны.', '', 'Параметр «Размещение» базы — «три зоны региона»; реплика и автопереключение должны быть включены.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 15, 'sd15-zone-cache', 2, 'lab', 'Кэш по зонам', 'В схеме есть кэш, но он стоит в одной зоне, а база без кэша не вытянет чтения: 3000 в секунду. Разместите кэш в трёх зонах с репликой (≥85% попаданий), чтобы схема переживала отказ зоны. Остальные компоненты уже размещены правильно.', '', 'У кэша — размещение «три зоны региона» и хотя бы одна реплика.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 15, 'sd15-region', 3, 'lab', 'Пережить отказ региона', 'Сервис должен пережить отказ целого региона, и ради этого размещается в двух регионах. После потери региона остаётся половина серверов. Переведите серверы, кэш и базу на размещение «два региона» и подберите число серверов: 3000 запросов в секунду должны вытягиваться и после отказа региона. Бюджет — $2800 в месяц.', '', 'Десять серверов M: после потери региона остаётся пять — 3500. Для кэша и базы нужны реплики (и автопереключение у базы).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 15, 'sd15-budget', 4, 'lab', 'Уровень надёжности под бюджет', 'Внутреннему сервису отчётов не нужен второй регион, но простой из-за потери зоны недопустим. Соберите схему, которая переживает отказ зоны и укладывается в $1600 в месяц, при нагрузке 1500 запросов в секунду. Не размещайте её в двух регионах — это дороже.', '', 'Размещение «три зоны региона»; серверов M — четыре или пять (после потери зоны остаётся 2/3), база M с репликой и автопереключением.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 15, 'sd15-final', 5, 'lab', 'Платёжный сервис в двух регионах', 'Итоговое упражнение главы. 3000 чтений и 300 записей в секунду, 150 ГБ данных, рабочий набор 12 ГБ. Соберите схему в двух регионах: серверы, кэш (≥85%) и база разнесены, схема переживает отказ зоны и региона, загрузка не выше 80%, бюджет — $4500 в месяц.', '', 'Серверов M — двенадцать (после потери региона шесть — 4200, после зоны восемь — 5600); кэш 12 ГБ с репликой; база L или M с репликой, автопереключением и размещением «два региона».', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 16, 'sd16-rolling', 0, 'lab', 'Выкладка по одному', 'Сейчас новая версия выкладывается на все серверы сразу: на время выкладки сервис недоступен. Переключите стратегию на «по одному» (rolling) и подберите число серверов, чтобы при обновлении (минус один сервер) оставшиеся вытягивали 1300 запросов в секунду. Схема должна переживать выкладку. Бюджет — $700 в месяц. Параметр «Выкладка» показан в упражнении.', '', 'Три сервера M: при обновлении остаётся два — 1400 запросов. Двух серверов мало: останется один (700).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 16, 'sd16-bluegreen', 1, 'lab', 'Когда запаса нет', 'Парк небольшой — два сервера M (1400 запросов), нагрузка 1300. Выкладка «по одному» оставит один сервер, этого мало, а покупать третий бюджет не позволяет. Выберите blue/green: пока идёт выкладка, мощность не падает. Не больше двух серверов, загрузка не выше 95%, стоимость — не больше $700 в месяц (blue/green удваивает расход на серверы).', '', 'Параметр «Выкладка» сервера — blue/green. Расход на серверы при этом ×2: 2 × 240 = 480.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 16, 'sd16-cost', 2, 'lab', 'Что дешевле: rolling или blue/green', 'Нагрузка выросла до 6000 запросов в секунду, и сейчас используется blue/green: расход на серверы удваивается. Сравните цены: при большом парке rolling обходится заметно дешевле. Переведите выкладку на «по одному» и подберите число серверов: схема переживает выкладку, загрузка не выше 90%, бюджет — $2200 в месяц.', '', 'Десять серверов M: при выкладке остаётся девять — 6300 запросов. Blue/green с девятью серверами обойдётся в 2160 за серверы — слишком дорого.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 16, 'sd16-zero-downtime', 3, 'lab', 'Выкладка и отказ зоны', 'Серверы должны пережить и выкладку (минус один сервер), и отказ зоны (минус треть). Нагрузка — 2000 запросов в секунду. Разместите серверы по трём зонам, включите rolling и подберите число серверов: схема переживает выкладку, отказ зоны и отказ сервера.', '', 'Четыре сервера M: при потере зоны останется два — 1400, мало. Пять: после потери зоны три — 2100, при выкладке четыре — 2800.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 16, 'sd16-final', 4, 'lab', 'Безопасная доставка', 'Итоговое упражнение главы. Магазин: 2500 запросов в секунду, кэш и база. Соберите схему, которая переживает выкладку (rolling), отказ зоны, отказ базы и кэша, с мониторингом: загрузка не выше 80%, бюджет — $3000 в месяц.', '', 'Серверов M — семь (после потери зоны пять — 3500); кэш с репликой в трёх зонах; база M с репликой и автопереключением в трёх зонах; мониторинг.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 17, 'sd17-reserved', 0, 'lab', 'Резерв для постоянной нагрузки', 'Нагрузка стабильна: 4000 запросов в секунду круглые сутки. Серверы оплачиваются по требованию. Переведите их на резервный тариф (параметр «Тариф» показан в упражнении) со скидкой около 40% и уложитесь в $1000 в месяц при загрузке не выше 80%.', '', 'Восемь серверов M по требованию стоят 960 за одни серверы — вместе с базой и балансировщиком больше 1200. С резервом — около 580 за серверы.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 17, 'sd17-spot-workers', 1, 'lab', 'Спот для обработчиков', 'Обработка заказов идёт через очередь, и обработчики терпят прерывание: сообщение вернётся в очередь. Переведите обработчиков на спот (втрое дешевле), сделайте обработку идемпотентной и оставьте не меньше двух обработчиков. Загрузка — не выше 85%, очередь разбирается без отставания (пик 10 с, допустимо 5 с), бюджет — $1200 в месяц.', '', 'Три обработчика M тянут 1200 в секунду при нагрузке 900. На споте они стоят около 72 в месяц вместо 240.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 17, 'sd17-rightsize', 2, 'lab', 'Слишком большие серверы', 'Сервис получает 2400 запросов в секунду, а на схеме шесть серверов L (ёмкость 9000): они загружены на 27%, и счёт огромный. Подберите правильный размер: загрузка серверов не выше 80%, но не больше — бюджет $1100 в месяц на всю схему (база — M с репликой).', '', 'Два сервера L дают 3000 запросов — 80%. Четыре сервера M — 2800: 86% — слишком много.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 17, 'sd17-cdn-cost', 3, 'lab', 'CDN дешевле серверов', 'Сайт отдаёт 12 000 запросов в секунду статики через серверы приложения: их приходится держать с запасом. Поставьте CDN (≥90%) и пересчитайте парк: загрузка не выше 80%, бюджет — $450 в месяц на всю схему.', '', 'С CDN статика почти не доходит до серверов: двух серверов M хватит. CDN стоит 60 в месяц, а лишний сервер M — 120.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 17, 'sd17-final', 4, 'lab', 'Тот же сервис дешевле', 'Итоговое упражнение главы. Магазин: 6000 запросов в секунду (1000 статики через CDN, остальное динамика), заказы идут через очередь. Сократите счёт, не потеряв надёжность: резервный тариф для серверов приложения, спот для идемпотентных обработчиков, CDN (≥90%), схема переживает отказ зоны и сервера, загрузка не выше 80%, бюджет — $3000 в месяц.', '', 'Серверов M — девять в трёх зонах (после потери зоны шесть — 4200), резервный тариф; три обработчика M на споте в трёх зонах; база M с тремя репликами и автопереключением в трёх зонах (после потери зоны остаются две реплики — 6000 чтений).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 18, 'sd18-s1-mvp', 0, 'lab', 'Этап 1. MVP', 'Сервис коротких видео стартует: 250 чтений и 30 записей метаданных в секунду. Соберите простейшую схему — пользователи, сервер приложения, база данных — и подберите размеры, чтобы загрузка не превышала 80%, а стоимость — $250 в месяц.', '', 'Сервер S тянет 300 запросов (280 — 93%): нужен M. База S подойдёт: 250 чтений и 30 записей — 40%.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 18, 'sd18-s2-growth', 1, 'lab', 'Этап 2. Рост в десять раз', 'Нагрузка выросла: 2500 чтений и 300 записей в секунду, рабочий набор — 5 ГБ. Усильте схему: балансировщик, несколько серверов, кэш метаданных (≥85%) и реплика базы с автопереключением. Схема переживает отказ базы, кэша и сервера, загрузка не выше 80%, бюджет — $1400 в месяц.', '', 'Пять серверов M; кэш 5 ГБ с TTL 3600 и репликой; база M (записей 300 — для S много) с репликой и автопереключением.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 18, 'sd18-s3-media', 2, 'lab', 'Этап 3. Видео и CDN', 'Пользователи начали смотреть ролики: 30 000 запросов в секунду за файлами. Вынесите их в объектное хранилище и поставьте CDN (≥90% статики) перед ним. Серверы приложения должны остаться на метаданных, загрузка — не выше 80%, схема остаётся устойчивой, бюджет — $1500 в месяц.', '', 'CDN → хранилище (статика мимо серверов); динамику CDN передаёт балансировщику. Остальное — как на втором этапе.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 18, 'sd18-s4-transcode', 3, 'lab', 'Этап 4. Перекодирование через очередь', 'Ролики нужно перекодировать после загрузки. Добавьте очередь и идемпотентных обработчиков на споте (не меньше двух): после пика в 10 секунд очередь разбирается без отставания (допустимо 5 с), база и серверы не выше 80%, бюджет — $1600 в месяц.', '', 'Сервер → очередь → обработчики → база. Два обработчика M на споте тянут 800 записей в секунду при нагрузке 300.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 18, 'sd18-s5-feed-search', 4, 'lab', 'Этап 5. Лента и поиск', 'Добавлены лента подписок (в среднем 100 подписчиков у автора) и поиск по названиям (15% чтений, индекс 160 ГБ). Выберите гибридную ленту, добавьте поисковый кластер (шарды по объёму, две реплики) и расширьте кэш до рабочего набора (8 ГБ, ≥85%). Схема переживает отказ базы и поиска, всё — не выше 80%, бюджет $3500 в месяц.', '', 'Лента — «гибрид» у сервера. Поиск: четыре шарда, две реплики (160 / 40 = 4). Кэш 8 ГБ с репликой. Гибридная лента удваивает записи, поэтому базе M уже тесно — нужна L.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 18, 'sd18-s6-reliability', 5, 'lab', 'Этап 6. Зоны и защита', 'Сервис стал критичным: нужно пережить отказ зоны, выкладки и сервера. Разнесите серверы, кэш, обработчиков и базу по трём зонам, включите rolling-выкладку, автомат разрыва, поставьте ограничитель на входе (предел не меньше обычной нагрузки 2800) и мониторинг. Загрузка не выше 80%, бюджет — $4200 в месяц.', '', 'Серверов M — девять в трёх зонах (после потери зоны шесть — 4200). Ограничитель между балансировщиком и серверами; мониторинг на схему.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 18, 'sd18-s7-cost', 6, 'lab', 'Этап 7. Сократить счёт', 'Счёт растёт, а нагрузка стабильна: серверы приложения нужны круглые сутки. Переведите их на резервный тариф (скидка около 40%), сохранив все цели надёжности: схема переживает отказ зоны, выкладки, сервера, базы и поиска, загрузка не выше 80%, бюджет — $3700 в месяц.', '', 'Параметр «Тариф» сервера приложения — «резерв». Остальное не трогайте: надёжность важнее экономии на ней.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 18, 'sd18-exam', 7, 'lab', 'Экзамен. Итоговая схема', 'Итоговое задание. Сервис в полной силе: 45 000 запросов в секунду за файлами, 3800 чтений и 450 записей в секунду, лента подписок (100 подписчиков у автора), поиск (15% чтений, индекс 240 ГБ), рабочий набор 10 ГБ. Соберите схему с нуля: CDN (≥90%) → хранилище; балансировщики (два), ограничитель (предел от 4300), серверы с rolling-выкладкой, автоматом разрыва и гибридной лентой; кэш (≥85%) с репликой; очередь с идемпотентными обработчиками на споте; поиск (шарды по объёму, две реплики); база с репликой и автопереключением; мониторинг. Схема переживает отказ зоны, выкладки, сервера, базы, кэша и поиска; доступность ≥ 99,9%, p99 ≤ 160 мс, загрузка не выше 80%, бюджет — $4700 в месяц.', '', 'Серверов M — одиннадцать в трёх зонах, резервный тариф; кэш 10 ГБ с репликой в трёх зонах; поиск 6 шардов × 2 реплики; три обработчика M на споте; база L с репликой в трёх зонах; всё остальное — по этапам предыдущих упражнений.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 19, 'sd19-s1-mvp', 0, 'lab', 'Этап 1. Первая версия', 'Облачный диск стартует: 200 чтений и 30 записей метаданных в секунду, 120 скачиваний файлов в секунду, 2 ТБ файлов. Добавьте объектное хранилище для содержимого файлов и свяжите его с сервером приложения: метаданные — в базе, байты — в хранилище. Загрузка не выше 80%, стоимость не больше $350 в месяц.', '', 'База хранит имена и права, хранилище — блоки файлов. Сервер → хранилище: файлы идут мимо базы. Хранилище стоит $25 плюс $23 за ТБ.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 19, 'sd19-s2-growth', 1, 'lab', 'Этап 2. Рост и метаданные', 'Пользователей стало в десять раз больше: 2400 чтений и 300 записей метаданных в секунду, 40 ТБ файлов. Усильте метаданные: балансировщик, несколько серверов, кэш листингов папок (≥85%, рабочий набор 4 ГБ), база с репликой и автопереключением. Схема переживает отказ базы и кэша, загрузка не выше 80%, бюджет — $2500 в месяц.', '', 'Пять серверов M, кэш 4 ГБ с репликой и TTL 3600, база M с репликой и автопереключением. Основные деньги уходят на хранение: 40 ТБ × $23.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 19, 'sd19-s3-cdn', 2, 'lab', 'Этап 3. Скачивания через CDN', 'Скачиваний стало 15 000 в секунду. Каждое идёт через хранилище с задержкой 45 мс. Поставьте CDN перед хранилищем (≥90% попаданий) и добейтесь средней задержки не больше 40 мс. Остальное — как на втором этапе, бюджет $2500 в месяц.', '', 'CDN → хранилище; динамику (метаданные) CDN передаёт балансировщику. Блоки неизменны, поэтому TTL 300 с и больше даёт 90% и выше.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 19, 'sd19-s4-sync', 3, 'lab', 'Этап 4. Синхронизация устройств', 'Добавлена синхронизация: 150 000 клиентов держат соединение и получают сигналы об изменениях (0,02 сигнала в секунду на клиента — 3000 в секунду). Поставьте шлюзы WebSocket, пропустите изменения через поток событий и подключите уведомления: шлюзы, серверы и уведомления загружены не выше 80%, бюджет — $4700 в месяц.', '', 'Шлюзы ws — около 14 (150 000 / 15 000 = 10 при 71%). Сервер приложения принимает и сигналы: около одиннадцати M. Поток событий с тремя партициями, уведомления — три экземпляра.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 19, 'sd19-s5-share', 4, 'lab', 'Этап 5. Права и поиск', 'Добавлены общий доступ и поиск: каждый запрос проверяет права в сервисе входа, а 10% чтений — поиск по файлам (индекс 80 ГБ). Подключите сервис входа (не больше 80% загрузки, переживает отказ) и поисковый кластер (шарды по объёму, две реплики, переживает отказ). Бюджет — $5600 в месяц.', '', 'Сервис входа: три экземпляра (по 4000 запросов в секунду; после отказа одного остаётся 8000 при нагрузке около 6000). Поиск: 2 шарда × 2 реплики.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 19, 'sd19-s6-storage', 5, 'lab', 'Этап 6. Стоимость хранения', 'Данных стало 900 ТБ, и хранилище съедает почти весь бюджет. Переведите файлы на более дешёвый класс хранения (параметр «Класс хранения»), чтобы схема укладывалась в $15 000 в месяц, средняя задержка оставалась не больше 40 мс (CDN прикрывает холодные блоки), а остальные цели не пострадали.', '', 'Горячее стоит $23 за ТБ — 20 700 в месяц. Смешанный класс — $10 за ТБ (9000), холодное — $4 (3600). Популярные блоки всё равно раздаёт CDN.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 19, 'sd19-s7-reliability', 6, 'lab', 'Этап 7. Надёжность и мониторинг', 'Диск стал критичным: данные пользователей нельзя терять, а простой должен быть короче минуты. Разнесите серверы, кэш и базу по трём зонам, включите rolling-выкладку, добавьте мониторинг и второй балансировщик. Схема переживает отказ зоны, выкладки, сервера, базы, кэша и сервиса входа, загрузка не выше 80%, бюджет — $16 000 в месяц.', '', 'Серверов M — около 14 в трёх зонах (после потери зоны остаются две трети). Два балансировщика, кэш и база размещены в трёх зонах с репликами, мониторинг на схему.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 19, 'sd19-exam', 7, 'lab', 'Экзамен. Облачный диск целиком', 'Итоговое задание. Соберите диск с нуля: объектное хранилище (800 ТБ, смешанный класс), CDN (≥90%), кэш листингов (≥85%), метаданные с репликой, WebSocket-шлюзы, поток событий и уведомления, сервис входа, поиск (шарды по объёму, две реплики), мониторинг, два балансировщика. Нагрузка: 15 000 скачиваний, 3800 чтений и 500 записей в секунду, 150 000 клиентов на соединениях. Схема переживает отказ зоны, выкладки, сервера, базы, кэша, сервиса входа и поиска; загрузка не выше 80%; средняя задержка ≤ 40 мс; бюджет — $15 000 в месяц.', '', 'Схема этапа 7 (база L: записей 500 в секунду): серверы M в трёх зонах (около 17: после потери зоны остаются 11 — 7700 запросов при нагрузке 7300), кэш и база с репликами, CDN → хранилище, ws → серверы → поток → уведомления, сервис входа ×3, поиск 2×2.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 20, 'sd20-s1-mvp', 0, 'lab', 'Этап 1. Первая версия', 'Фотосеть стартует: 400 чтений и 60 записей метаданных в секунду, 300 запросов фото в секунду, 5 ТБ снимков. Храните снимки в объектном хранилище, метаданные — в базе. Загрузка не выше 80%, стоимость не больше $450 в месяц.', '', 'Сервер → база (метаданные) и сервер → хранилище (снимки). Хранилище стоит $25 плюс $23 за ТБ — 140.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 20, 'sd20-s2-processing', 1, 'lab', 'Этап 2. Обработка фото', 'Публикаций стало 300 в секунду, и каждую нужно обработать: сделать размеры и превью. Добавьте очередь и идемпотентных обработчиков на споте (не меньше двух), которые читают очередь и записывают результат в базу и хранилище. После пика в 10 секунд очередь разбирается без отставания (допустимо 5 с), база не выше 80%, бюджет — $1300 в месяц.', '', 'Сервер → очередь → обработчики → база и хранилище. Два обработчика M тянут 800 в секунду при нагрузке 300. Параметры «Тариф» и «Идемпотентная обработка» показаны в упражнении.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 20, 'sd20-s3-cdn', 2, 'lab', 'Этап 3. Раздача через CDN', 'Просмотров снимков стало 25 000 в секунду. Поставьте CDN перед хранилищем с высокой долей попаданий (≥95%, неизменные адреса позволяют долгий TTL), чтобы средняя задержка была не больше 40 мс, серверы и остальное — не выше 80%, а бюджет — $2000 в месяц.', '', 'CDN → хранилище, TTL 3600 даёт 98%. Динамику CDN передаёт балансировщику. Серверов M понадобится семь, база — L.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 20, 'sd20-s4-feed', 3, 'lab', 'Этап 4. Лента подписок', 'Появилась лента подписок: 5000 открытий в секунду, у автора в среднем 150 подписчиков, 30 ТБ снимков. Выберите гибридную ленту, поставьте кэш лент и метаданных (≥90%, рабочий набор 8 ГБ), усильте базу репликой с автопереключением (запись тяжелее: нужна база L) и обработчиков под удвоенную запись. Всё не выше 80%, схема переживает отказ базы и кэша, бюджет — $3900 в месяц.', '', 'Гибрид умножает запись в 2,5 раза (750 в секунду). Три обработчика M, база L с репликой, кэш 8 ГБ с репликой, серверов M — десять.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 20, 'sd20-s5-events', 4, 'lab', 'Этап 5. События и уведомления', 'Каждое действие — событие. Подключите поток событий (три партиции) к серверу, а к потоку — уведомления и аналитику: потребители должны быть загружены не выше 80%. Уведомлений должно хватить и на пуши при отказе одного экземпляра, бюджет — $4300 в месяц.', '', 'Сервер → поток → уведомления и аналитика. Событий около 300 в секунду; два экземпляра уведомлений (по 1500) и один аналитики.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 20, 'sd20-s6-explore', 5, 'lab', 'Этап 6. Рекомендации и поиск', 'Раздел рекомендаций обращается к сервису ранжирования на 20% запросов (около 1060 в секунду; один экземпляр тянет 300), каждый запрос проверяет сервис входа, а 8% чтений — поиск (индекс 200 ГБ). Подключите сервис ранжирования, сервис входа и поиск: загрузка не выше 80%, схема переживает отказ ранжирования, входа и поиска, бюджет — $7200 в месяц.', '', 'Ранжирование: пять экземпляров (1500; при отказе одного остаётся 1200 при нагрузке 1060). Вход: три экземпляра (после отказа одного остаётся 8000 при нагрузке 5300). Поиск: 5 шардов × 2 реплики (200 / 40).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 20, 'sd20-s7-reliability', 6, 'lab', 'Этап 7. Надёжность, защита и деньги', 'Фотосеть должна открываться всегда. Разнесите серверы, кэш, обработчиков и базу по трём зонам, включите rolling-выкладку, добавьте второй балансировщик, ограничитель на входе (предел не меньше обычной нагрузки 5300) и мониторинг, переведите хранилище на смешанный класс (30 ТБ). Схема переживает отказ зоны, выкладки, сервера, базы и кэша, загрузка не выше 80%, бюджет — $8000 в месяц.', '', 'Серверов M — 12 в трёх зонах (после потери зоны остаётся 8 — 5600). Ограничитель между балансировщиком и серверами, предел около 12 000. Класс хранения у хранилища — смешанный.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 20, 'sd20-exam', 7, 'lab', 'Экзамен. Фотосеть целиком', 'Итоговое задание. Фотосеть в полной силе: 40 000 запросов в секунду за снимками, 7000 открытий ленты и 400 публикаций в секунду, 600 ТБ снимков, у автора в среднем 150 подписчиков, 250 ГБ метаданных (рабочий набор 10 ГБ). Соберите схему с нуля: хранилище (смешанный класс) и CDN (≥95%), кэш (≥90%), гибридная лента, очередь с идемпотентными обработчиками на споте, поток событий с уведомлениями и аналитикой, сервис ранжирования (20% запросов), сервис входа, поиск, ограничитель, мониторинг, два балансировщика. Переживает отказ зоны, выкладки, сервера, базы, кэша, ранжирования, входа и поиска; загрузка не выше 80%; средняя задержка ≤ 40 мс; бюджет — $18 000 в месяц.', '', 'Серверов M — 17 в трёх зонах; база L с 2 шардами и репликой (запись удваивается лентой); ранжирование — 7 экземпляров, вход — 3, поиск 6×2 (250 ГБ), обработчиков M — 4, кэш 10 ГБ с репликой.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 21, 'sd21-s1-mvp', 0, 'lab', 'Этап 1. Первая версия и геосервис', 'Сервис такси стартует: 300 чтений и 60 заказов в секунду, а 800 водителей присылают позицию каждые несколько секунд. Половина запросов — поиск ближайших водителей. Сохраните заказы в базе, а позиции и поиск отдайте геосервису: свяжите сервер с геосервисом. Загрузка не выше 80%, бюджет — $350 в месяц.', '', 'Позиции пишутся не в базу, а в геосервис в памяти (6000 обновлений в секунду на экземпляр). Сервер → геосервис.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 21, 'sd21-s2-geo', 1, 'lab', 'Этап 2. Поток позиций', 'Город вырос: 3000 чтений и 500 заказов в секунду, 20 000 обновлений позиций в секунду, каждый запрос проверяет сервис входа. Масштабируйте геосервис и добавьте сервис входа: загрузка не выше 80%, схема переживает отказ геосервиса и сервиса входа, база L (записи поездок), бюджет — $2400 в месяц.', '', 'Геосервис: 5 экземпляров (30 000; после отказа одного остаётся 24 000 при нагрузке 21 750). Вход: 2 экземпляра. Серверов M — 7, база L.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 21, 'sd21-s3-eta', 2, 'lab', 'Этап 3. Время подъезда', 'Подбор водителя оценивает время подъезда моделью: она вызывается на 25% запросов (около 875 в секунду), а один экземпляр тянет 300. Подключите сервис ранжирования: загрузка не выше 80%, схема переживает отказ ранжирования, бюджет — $3200 в месяц.', '', 'Четыре экземпляра ранжирования: 1200 запросов в секунду, после отказа одного остаётся 900.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 21, 'sd21-s4-tracking', 3, 'lab', 'Этап 4. Отслеживание и события', 'Пассажиры видят машину на карте: 150 000 соединений получают по 0,02 обновления в секунду (3000 в секунду). Поставьте шлюзы WebSocket, пропустите события через поток и подключите уведомления и аналитику (спрос для цены): шлюзы, серверы и потребители — не выше 80%, бюджет — $5600 в месяц.', '', 'Шлюзов ws — 13 (150 000 / 15 000 = 10 при 77%). Серверов M теперь 12 (принимают и обновления). Уведомления — 4 экземпляра (3500 событий), аналитика — 1.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 21, 'sd21-s5-pay', 4, 'lab', 'Этап 5. Платежи', 'Добавлены платежи: 4% запросов обращаются к внешнему платёжному шлюзу (180 мс, один канал тянет 400). Подключите шлюз с двумя каналами (отказ одного не должен останавливать оплату) и защитите платежи: ключи идемпотентности, повторы и автомат разрыва в приложении. Схема переживает отказ платёжного канала, бюджет — $5700 в месяц.', '', 'Сервер → платёжный шлюз, каналов — 2. В приложении включите «Ключи идемпотентности», «Повторы к БД» — не меньше 1, «Автомат разрыва».', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 21, 'sd21-s6-reliability', 5, 'lab', 'Этап 6. Надёжность и пики', 'Сервис критичен: пассажир под дождём ждать не будет. Разнесите серверы и базу по зонам, включите rolling-выкладку, добавьте реплику базы с автопереключением, второй балансировщик, ограничитель на входе (предел не меньше нагрузки 6500) и мониторинг. Схема переживает отказ зоны, выкладки, сервера, базы, геосервиса, ранжирования, сервиса входа и платёжного канала; загрузка не выше 80%; бюджет — $7000 в месяц.', '', 'Серверов M — 16 в трёх зонах (после потери зоны остаётся 10 — 7000 при нагрузке 6500). Предел ограничителя около 20 000. База L с репликой и автопереключением.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 21, 'sd21-exam', 6, 'lab', 'Экзамен. Сервис такси целиком', 'Итоговое задание. Крупный город в пик: 6000 чтений и 1000 заказов в секунду, 60 000 обновлений позиций, 300 000 соединений для отслеживания (3000 сигналов в секунду); половина запросов идёт в геосервис, 25% — в ранжирование, 4% — в платёжный шлюз, каждый проверяет вход. Соберите схему с нуля: геосервис, ранжирование, сервис входа, платёжный шлюз (2 канала), поток событий с уведомлениями и аналитикой, шлюзы WebSocket, база L с шардами и репликой, ограничитель, мониторинг, два балансировщика, защита платежей. Переживает отказ зоны, выкладки, сервера, базы, геосервиса, ранжирования, входа и платёжного канала; загрузка не выше 80%; бюджет — $13 000 в месяц.', '', 'Серверов M — 23 в трёх зонах, геосервис 14, ранжирование 8, вход 3, шлюзы ws 26, уведомления 4; база L с двумя шардами и репликой.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 22, 'sd22-s1-graph', 0, 'lab', 'Этап 1. Профили, друзья и горячие ключи', 'Сеть растёт: 3000 чтений и 2000 записей в секунду (посты, лайки, заявки в друзья), а 12% запросов приходится на самые популярные профили и сообщества. Одна база не вытянет запись. Поставьте кэш (≥75%: записей много, поэтому кэш отдаёт меньше обычного; рабочий набор 10 ГБ) и шардируйте базу по хешу так, чтобы загрузка не превышала 80%, а на самый нагруженный шард приходилось не больше 45% запросов. Бюджет — $3500 в месяц.', '', 'База L с тремя шардами по хешу: на горячий шард придётся 12% + 88%/3 ≈ 41% запросов. Серверов M — 9, кэш 10 ГБ.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 22, 'sd22-s2-feed', 1, 'lab', 'Этап 2. Лента новостей', 'Лента собирается из друзей и сообществ: 6000 открытий и 600 публикаций в секунду, у автора в среднем 120 подписчиков. Выберите гибрид, добавьте очередь с идемпотентными обработчиками на споте (рассылка в ленты идёт через неё, после пика в 10 секунд — без отставания): всё не выше 80%, бюджет — $4100 в месяц.', '', 'Гибрид умножает запись в 2,2 раза. Обработчики M — 5 (запись 1320 в секунду), база L с тремя шардами, серверов M — 12.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 22, 'sd22-s3-messages', 2, 'lab', 'Этап 3. Личные сообщения', 'Сообщения: 200 000 соединений получают по 0,02 события в секунду (4000 в секунду); идентификаторы растут со временем, а база шардирована по диапазонам — все новые сообщения попадают в последний шард. Смените способ шардирования, добавьте шлюзы WebSocket, поток событий и уведомления: на самый нагруженный шард не больше 45%, шлюзы и уведомления — не выше 80%, бюджет — $7300 в месяц.', '', 'Параметр «Ключ шардирования» базы — хеш. Шлюзов ws — 17 (200 000 / 15 000 = 13,3 при 78%). Серверов M — 20 (принимают и сообщения), уведомления — 5 экземпляров.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 22, 'sd22-s4-media', 3, 'lab', 'Этап 4. Фото, музыка и видео', 'Медиа: 30 000 запросов в секунду за файлами, 1500 ТБ в хранилище. Поставьте CDN перед хранилищем (≥95%) и переведите файлы на дешёвый класс хранения: горячее стоит $23 за ТБ — это 34 500 в месяц. Загрузка не выше 80%, бюджет — $23 000 в месяц.', '', 'CDN → хранилище, TTL 3600. Класс хранения «горячее + холодное» — $10 за ТБ (15 000), «холодное» — $4. Параметр показан в упражнении.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 22, 'sd22-s5-search', 4, 'lab', 'Этап 5. Поиск, права и рекомендации', 'Добавлены поиск людей и сообществ (10% чтений, индекс 200 ГБ), проверка прав на каждый запрос и рекомендации (20% запросов обращаются к сервису ранжирования). Подключите поиск, сервис входа и ранжирование: загрузка не выше 80%, схема переживает отказ каждого из них, бюджет — $26 500 в месяц.', '', 'Поиск: 5 шардов × 2 реплики. Вход: 3 экземпляра (нагрузка 6600 запросов). Ранжирование: 6 экземпляров (1320 запросов, после отказа одного — 1500).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 22, 'sd22-s6-reliability', 5, 'lab', 'Этап 6. Надёжность и защита', 'Сеть нельзя ронять. Разнесите серверы, кэш, обработчиков и базу по зонам, включите rolling-выкладку, реплику базы с автопереключением, второй балансировщик, ограничитель на входе (предел не меньше нагрузки 10 600) и мониторинг. Схема переживает отказ зоны, выкладки, сервера, базы и кэша, загрузка не выше 80%, бюджет — $31 000 в месяц.', '', 'Серверов M — 24 в трёх зонах (после потери зоны остаётся 16 — 11 200 при нагрузке 10 600). База L с тремя шардами и репликой, предел ограничителя около 20 000.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 22, 'sd22-exam', 6, 'lab', 'Экзамен. Социальная сеть целиком', 'Итоговое задание. Сеть в пик: 9000 чтений и 1500 записей в секунду (12% — самые популярные профили и сообщества), 40 000 запросов за медиа, 300 000 соединений для сообщений (4500 событий в секунду), 1500 ТБ файлов, поиск (индекс 400 ГБ), рекомендации на 20% запросов, права на каждый запрос. Соберите схему с нуля: CDN и хранилище с дешёвым классом, кэш, гибридная лента через очередь и обработчиков на споте, база по хешу с шардами и репликой, шлюзы WebSocket, поток с уведомлениями и аналитикой, поиск, вход, ранжирование, ограничитель, мониторинг, два балансировщика. Переживает отказ зоны, выкладки, сервера, базы, кэша, поиска, входа и ранжирования; загрузка не выше 80%; бюджет — $36 000 в месяц.', '', 'Серверов M — 33 в трёх зонах, обработчиков M — 11, база L с 4 шардами по хешу и репликой, шлюзы ws — 26, уведомления — 6, ранжирование — 9, вход — 4, поиск — 10 шардов × 2, кэш 16 ГБ.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 23, 'sd23-s1-catalog', 0, 'lab', 'Этап 1. Каталог ресторанов', 'Каталог: 3000 открытий в секунду, половина из них — поиск ресторанов рядом по кухне и адресу, остальное — карточки и меню. Добавьте поисковый индекс и кэш меню (≥85%, рабочий набор 3 ГБ). Поиск и всё остальное — не выше 80%, схема переживает отказ реплики поиска, бюджет — $1800 в месяц.', '', 'Поиск: 1 шард × 3 реплики (1500 запросов в секунду; после отказа одной остаётся 2400). Кэш 3 ГБ с TTL 3600. Серверов M — 6.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 23, 'sd23-s2-order', 1, 'lab', 'Этап 2. Заказ и оплата', 'Оформление заказа: каждый запрос проверяет вход, а 5% обращаются к платёжному шлюзу. Подключите сервис входа (2 экземпляра) и платёжный шлюз с двумя каналами; защитите платежи: ключи идемпотентности, повторы и автомат разрыва. Схема переживает отказ входа и платёжного канала, бюджет — $2200 в месяц.', '', 'Сервер → вход и шлюз. В приложении включите «Ключи идемпотентности», «Повторы к БД» ≥ 1 и «Автомат разрыва». Вход ×2: после отказа остаётся 4000 при нагрузке 3100.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 23, 'sd23-s3-couriers', 2, 'lab', 'Этап 3. Курьеры и время доставки', 'Добавлены курьеры: 20 000 обновлений позиций в секунду, 10% запросов подбирают курьера в геосервисе, ещё 10% оценивают время доставки моделью. Подключите геосервис и сервис ранжирования: загрузка не выше 80%, схема переживает отказ обоих, бюджет — $3200 в месяц.', '', 'Геосервис: 5 экземпляров (30 000; после отказа одного — 24 000). Ранжирование: 3 экземпляра (900; после отказа — 600 при нагрузке 312).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 23, 'sd23-s4-tracking', 3, 'lab', 'Этап 4. Отслеживание и события', 'Клиенты следят за заказом: 120 000 соединений получают по 0,03 события в секунду (3600 в секунду). Поставьте шлюзы WebSocket, пропустите события через поток и подключите уведомления и аналитику (спрос и время приготовления): шлюзы и потребители — не выше 80%, бюджет — $5200 в месяц.', '', 'Шлюзов ws — 11 (120 000 / 15 000 = 8 при 73%). Серверов M — 13 (принимают и события). Уведомления — 4 экземпляра.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 23, 'sd23-s5-reliability', 4, 'lab', 'Этап 5. Надёжность и пики', 'К обеденному пику сервис должен быть готов. Разнесите серверы и базу по зонам, добавьте реплику базы с автопереключением, CDN для картинок меню, ограничитель на входе (предел не меньше нагрузки 6700), второй балансировщик и мониторинг. Схема переживает отказ зоны, выкладки, сервера, базы, кэша и поиска, загрузка не выше 80%, бюджет — $7000 в месяц.', '', 'Серверов M — 18 в трёх зонах (после потери зоны остаётся 12 — 8400 при нагрузке 6700). База L с репликой, предел ограничителя около 20 000.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 23, 'sd23-exam', 5, 'lab', 'Экзамен. Доставка еды целиком', 'Итоговое задание. Обеденный пик крупного города: 9000 открытий каталога (половина — поиск) и 600 заказов в секунду, 40 000 обновлений позиций курьеров, 200 000 соединений для слежения за заказами (6000 событий в секунду); 10% запросов подбирают курьера, 10% оценивают время, 5% идут в платёжный шлюз, каждый проверяет вход. Соберите схему с нуля: поиск, кэш меню, вход, платёжный шлюз (2 канала), геосервис, ранжирование, поток с уведомлениями и аналитикой, шлюзы WebSocket, CDN, база с репликой, ограничитель, мониторинг, два балансировщика и защита платежей. Переживает отказ зоны, выкладки, сервера, базы, кэша, поиска, входа, платёжного канала, геосервиса и ранжирования; загрузка не выше 80%; бюджет — $12 500 в месяц.', '', 'Серверов M — 35 в трёх зонах, поиск 1×5 (4500 запросов в секунду), геосервис 10, ранжирование 5, вход 4, шлюзы ws 18, уведомления 7, аналитика 2, база L с репликой.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 24, 'sd24-s1-storage', 0, 'lab', 'Этап 1. Хранилище чатов', 'Сообщения: 5000 чтений истории и 3000 записей в секунду, 600 ГБ, идентификаторы сообщений растут со временем, а 10% запросов приходится на самые активные чаты. База сейчас шардирована по диапазонам — все новые сообщения идут в последний шард. Смените способ шардирования, поставьте кэш свежих сообщений (≥70%; рабочий набор 8 ГБ): загрузка не выше 80%, на самый нагруженный шард не больше 45% запросов, бюджет — $3600 в месяц.', '', 'Ключ шардирования — хеш от идентификатора чата. База L с тремя шардами: на горячий шард придётся 10% + 90%/3 = 40%. Серверов M — 8, кэш 8 ГБ.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 24, 'sd24-s2-gateways', 1, 'lab', 'Этап 2. Шлюзы, поток и пуши', 'Добавлены постоянные соединения: 300 000 клиентов получают по 0,02 события в секунду (6000 в секунду). Поставьте шлюзы WebSocket, пропустите события через поток, подключите уведомления для тех, кто не в сети, и аналитику (задержка доставки, потери). Шлюзы и потребители — не выше 80%, бюджет — $8200 в месяц.', '', 'Шлюзов ws — 26 (300 000 / 15 000 = 20 при 77%). Серверов M — 22 (принимают и события), уведомления — 8, аналитика — 2.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 24, 'sd24-s3-groups', 2, 'lab', 'Этап 3. Группы и каналы', 'Группы: в среднем сообщение получают 100 участников, запись в хранилище умножается. Рассылку в группы ведёт очередь с идемпотентными обработчиками на споте; после пика в 10 секунд отставания быть не должно. Всё не выше 80%, бюджет — $8700 в месяц.', '', 'Очередь и обработчики M — 14 (запись в хранилище умножается на 100 получателей), связь приложение → очередь → обработчики → база. Цена на споте ниже, идемпотентность включена.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 24, 'sd24-s4-media', 3, 'lab', 'Этап 4. Фото и видео в переписках', 'Вложения: 20 000 запросов в секунду за файлами, 800 ТБ в хранилище. Поставьте CDN перед хранилищем (≥95%) и переведите файлы на дешёвый класс хранения: горячее стоит $23 за ТБ — это 18 400 в месяц. Загрузка не выше 80%, бюджет — $17 000 в месяц.', '', 'CDN → хранилище, TTL 3600. Класс хранения «горячее + холодное» — $10 за ТБ (20 000), «холодное» — $4.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 24, 'sd24-s5-abuse', 4, 'lab', 'Этап 5. Вход и защита от спама', 'Каждый запрос проверяет вход, а 10% сообщений проходят через сервис ранжирования, который отсекает спам. Подключите сервис входа и ранжирование: загрузка не выше 80%, схема переживает отказ каждого из них, бюджет — $18 000 в месяц.', '', 'Вход: 3 экземпляра, ранжирование: 4 (после отказа одного остаётся 900 запросов).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 24, 'sd24-s6-reliability', 5, 'lab', 'Этап 6. Надёжность и регионы', 'Мессенджер не должен молчать. Разнесите серверы, кэш, обработчиков и базу по зонам, включите rolling-выкладку, реплику базы с автопереключением, второй балансировщик, ограничитель на входе (предел не меньше нагрузки 8000) и мониторинг. Схема переживает отказ зоны, выкладки, сервера, базы, кэша, входа и ранжирования, загрузка не выше 80%, бюджет — $20 500 в месяц.', '', 'Серверов M — 26 в трёх зонах. База L с тремя шардами и репликой, предел ограничителя около 20 000.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (18, 24, 'sd24-exam', 6, 'lab', 'Экзамен. Мессенджер целиком', 'Итоговое задание. Мессенджер в пик: 4500 чтений истории и 2500 сообщений в секунду, 600 ГБ с активными чатами (10% запросов), 320 000 соединений (6400 событий в секунду), группы по 100 участников, 22 000 запросов за вложениями, 800 ТБ файлов, вход на каждый запрос, 10% сообщений проходят антиспам. Соберите схему с нуля: кэш, база по хешу с шардами и репликой, шлюзы WebSocket, поток с уведомлениями и аналитикой, очередь и обработчики на споте, CDN и дешёвый класс хранения, вход, ранжирование, ограничитель, мониторинг, два балансировщика. Переживает отказ зоны, выкладки, сервера, базы, кэша, входа и ранжирования; загрузка не выше 80%; бюджет — $24 000 в месяц.', '', 'Серверов M — 30 в трёх зонах, шлюзы ws — 34, обработчиков M — 16, база L с четырьмя шардами и репликой, уведомления — 8, вход — 4, ранжирование — 5.', '{}');
